//! Opt-in owner-side batching contract between the accept loop and a backend
//! that keeps several requests in flight on its owner thread
//! ([`GenerationBackend::max_active`](super::http::GenerationBackend::max_active)
//! above one). Single-flight backends never see these types.
//!
//! The owner never blocks on a client: a [`BatchSink`] queues generated bytes
//! and delivers them with non-blocking sends; a request whose client cannot
//! keep up stays queued (the backend parks it) instead of stalling the others.
use super::http::{BackendFailure, GenerationOutcome, PreparedResponse};
use super::items::ServeError;
use std::io;
use std::sync::Arc;
use std::sync::atomic::AtomicBool;

/// Owner-side output and lifecycle of one submitted request.
pub(crate) trait BatchSink {
    /// The request's own cancellation (HTTP worker exit or disconnect).
    fn cancellation_flag(&self) -> Arc<AtomicBool>;
    /// Additional future CPU buffer allowance, beyond resident request storage.
    fn transport_reserve_bytes(&self) -> u64;
    /// Request cancellation, server gate and process signals; never blocks.
    fn check(&self) -> io::Result<()>;
    /// Queue one generated piece for delivery by [`Self::flush`].
    fn queue(&mut self, bytes: &[u8]);
    /// Deliver queued bytes without waiting. `Ok(true)` when nothing remains
    /// queued; `Ok(false)` when the client has not drained earlier output.
    fn flush(&mut self) -> io::Result<bool>;
    /// Publish the terminal result, then close the piece stream. Exactly once
    /// per request; flush first: bytes still queued here are dropped.
    fn complete(self: Box<Self>, result: Result<GenerationOutcome, BackendFailure>);
}

/// A prepared request handed to the backend's scheduler.
pub(crate) struct Job {
    pub(crate) prepared: Arc<PreparedResponse>,
    pub(crate) sink: Box<dyn BatchSink>,
}

/// Terminal for a submitted request that never started because the server
/// is stopping: the same busy envelope queued connections receive.
pub(crate) fn shutting_down() -> ServeError {
    ServeError {
        status: 503,
        error_type: "server_busy",
        code: Some("server_busy"),
        param: None,
        message: "server is shutting down".into(),
    }
}
